WITH base AS (SELECT id, device, started_at, country, CONCAT(browser, ' - ', device) AS browser_device FROM sessions WHERE started_at >= TO_TIMESTAMP('2023-05-21 10:00:00') AND country = 'JP') SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) FILTER (WHERE device = 'tablet') AS tablet_rows, COUNT(*) FILTER (WHERE country = 'JP') AS jp_rows FROM base GROUP BY DATE_TRUNC('MONTH', started_at);
